import { useEffect, useMemo } from 'react';

import { TemplateSlide } from 'components';
import { FilterDataAccessor } from 'domain/Filter';
import { usePageFilterApplied, usePageFilterData, usePageIndexes } from 'hooks';
import {
  CountrySlide,
  EvolutionSlide,
} from 'pages/components/PortfolioBrand/Slides';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { BRAND_POWER_BOOK_EXPORT_PAGE_NAME } from '../../../BrandPowerBookExport';
import { StyledContent } from '../../../BrandPowerBookExport.styles';
import {
  AI_SUMMARY_COUNTRY_IDENTIFIER,
  pageSections,
} from '../../../constants';
import { usePowerBookCountryData } from '../../../hooks/usePowerBookCountryData/usePowerBookCountryData';
import { usePowerBookPeriods } from '../../../hooks/usePowerBookPeriods/usePowerBookPeriods';
import { SubCover } from '../../SubCover/SubCover';
import {
  buildCountrySlideProps,
  buildEvolutionInfos,
} from '../CountryInline/utils';

interface CountryViewProps {
  containerRef: React.RefObject<HTMLElement>;
  loadingCallback: (loading: boolean) => void;
}

export const CountryView = ({
  containerRef,
  loadingCallback,
}: CountryViewProps) => {
  const { dataFilters } = usePageFilterData(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const { applied } = usePageFilterApplied(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const country = FilterDataAccessor.getInstance().getCountry(
    dataFilters,
    applied,
  );
  const countryCode = country?.value as string | undefined;
  const { getPageByName, updateIndexes } = usePageIndexes(containerRef);
  const {
    qtdPeriod: quarterYear,
    ytdPeriod,
    qtdCoverPrefix,
  } = usePowerBookPeriods();

  const { qtdData, ytdData, isLoadingCountryData, error } =
    usePowerBookCountryData(countryCode);

  const evolutionInfos = useMemo(() => {
    const infos = buildEvolutionInfos(
      qtdData?.overview,
      qtdData?.overviewMegabrands,
      isLoadingCountryData,
    );
    return [
      {
        ...infos[0],
        evolutionSlideError: error,
        aiSummary: AI_SUMMARY_COUNTRY_IDENTIFIER['power-evolution-all'],
      },
      {
        ...infos[1],
        evolutionSlideError: error,
        aiSummary: AI_SUMMARY_COUNTRY_IDENTIFIER['power-evolution-megabrands'],
      },
    ];
  }, [qtdData, isLoadingCountryData, error]);

  useEffect(() => {
    loadingCallback(isLoadingCountryData);
  }, [isLoadingCountryData, loadingCallback]);

  useEffect(() => {
    updateIndexes();
  }, [updateIndexes]);

  return (
    <>
      <StyledExportPageSection data-page-name={pageSections.countryTrends}>
        <TemplateSlide
          title={`${String(country?.label)} ABI: Power Evolution`}
          period={quarterYear}
          footnotes={
            applied.country === 'DOM' ? (
              <>
                <b>About results:</b> Results before 2022 exclude the Dominican
                Republic in the survey.
              </>
            ) : undefined
          }
          page={getPageByName(pageSections.countryTrends)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryTrends}
        >
          <StyledContent>
            <EvolutionSlide
              evolutionSlideInfos={evolutionInfos}
              alerts={[]}
              dataTestId="slide-evolution-country"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryQtdCover}>
        <SubCover
          title={quarterYear}
          countryCode={countryCode ?? ''}
          countryName={String(country?.label)}
        />
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryPerformance}>
        <TemplateSlide
          title={`${country?.label} ABI: ${qtdCoverPrefix} Performance`}
          period={quarterYear}
          footnotes=""
          page={getPageByName(pageSections.countryPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(qtdData, false)}
              loading={isLoadingCountryData}
              error={error}
              alerts={[]}
              dataTestId="slide-country-abi"
              aiSummary={AI_SUMMARY_COUNTRY_IDENTIFIER['performance-abi']}
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection
        data-page-name={pageSections.countryCompetitorPerformance}
      >
        <TemplateSlide
          title={`${country?.label} Competition: ${qtdCoverPrefix} Performance`}
          period={quarterYear}
          footnotes=""
          page={getPageByName(pageSections.countryCompetitorPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryCompetitorPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(qtdData, true)}
              loading={isLoadingCountryData}
              error={error}
              alerts={[]}
              dataTestId="slide-country-competitor"
              aiSummary={
                AI_SUMMARY_COUNTRY_IDENTIFIER['performance-competitor']
              }
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryYtdCover}>
        <SubCover
          title={ytdPeriod}
          countryCode={countryCode ?? ''}
          countryName={String(country?.label)}
        />
      </StyledExportPageSection>

      <StyledExportPageSection
        data-page-name={pageSections.countryYtdPerformance}
      >
        <TemplateSlide
          title={`${country?.label} ABI: YTD Performance`}
          period={ytdPeriod}
          footnotes=""
          page={getPageByName(pageSections.countryYtdPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryYtdPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(ytdData, false)}
              loading={isLoadingCountryData}
              error={error}
              alerts={[]}
              dataTestId="slide-country-ytd-abi"
              aiSummary={AI_SUMMARY_COUNTRY_IDENTIFIER['ytd-performance-abi']}
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection
        data-page-name={pageSections.countryYtdCompetitorPerformance}
      >
        <TemplateSlide
          title={`${country?.label} Competition: YTD Performance`}
          period={ytdPeriod}
          footnotes=""
          page={
            getPageByName(pageSections.countryYtdCompetitorPerformance)?.index
          }
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryYtdCompetitorPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(ytdData, true)}
              loading={isLoadingCountryData}
              error={error}
              alerts={[]}
              dataTestId="slide-country-ytd-competitor"
              aiSummary={
                AI_SUMMARY_COUNTRY_IDENTIFIER['ytd-performance-competitor']
              }
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>
    </>
  );
};
